def has_cycle_of_length(adj, n, length):
    """Check if graph has a cycle of given length"""
    # BFS from each vertex
    from collections import deque
    for start in range(n):
        # BFS tracking path
        queue = deque([(start, [start])])
        visited_at_depth = {start: 0}
        while queue:
            u, path = queue.popleft()
            if len(path) == length:
                # Check if we can close the cycle
                if start in adj[u]:
                    return True
                continue
            for v in adj[u]:
                if v == start and len(path) >= 3:
                    if len(path) == length - 1:
                        return True
                elif v not in path:
                    if len(path) < length - 1:
                        queue.append((v, path + [v]))
    return False

def check_girth(adj, n, min_girth):
    """Check if graph has girth at least min_girth"""
    from collections import deque
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_girth:
