    return True

def is_k_colorable(adj, n, k):
    """Check if graph is k-colorable using backtracking"""
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for u in adj[v]:
                if u < v and colors[u] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

