def check_girth_fast(adj, n, min_girth):
    """Check girth using BFS from each vertex"""
    from collections import deque
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_girth:
                        return False, cycle_len
    return True, float('inf')

def is_4_colorable(adj, n):
    """Check 4-colorability with backtracking and MRV heuristic"""
    colors = [-1] * n
    domains = [set(range(4)) for _ in range(n)]

    def get_neighbors(v):
        return [u for u in adj[v] if colors[u] != -1]

    def backtrack():
        # Find uncolored vertex with minimum remaining values
        uncolored = [v for v in range(n) if colors[v] == -1]
        if not uncolored:
            return True

        # MRV heuristic
        v = min(uncolored, key=lambda x: len(domains[x]))

        for c in list(domains[v]):
            # Check consistency
            valid = True
            for u in adj[v]:
                if colors[u] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                # Update domains
                old_domains = []
                for u in adj[v]:
                    if colors[u] == -1 and c in domains[u]:
                        old_domains.append(u)
                        domains[u].discard(c)
                        if not domains[u]:
                            valid = False
                            break

                if valid and backtrack():
                    return True

                # Restore
                colors[v] = -1
                for u in old_domains:
                    domains[u].add(c)

        return False

    return backtrack()

