n = 15

def check_girth_bfs(adj, n, min_girth):
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_girth:
                        return False
    return True

def can_add_edge(adj, u, v, n, min_girth):
    dist = {u: 0}
    queue = deque([u])
    while queue:
        curr = queue.popleft()
        if dist[curr] >= min_girth - 2:
            continue
        for w in adj[curr]:
            if w not in dist:
                dist[w] = dist[curr] + 1
                if w == v:
                    if dist[w] < min_girth - 1:
                        return False
                queue.append(w)
    return True

def is_4_colorable(adj, n):
    colors = [-1] * n
    def backtrack(v):
        if v == n:
            return True
        for c in range(4):
            valid = all(colors[u] != c for u in adj[v] if u < v)
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False
    return backtrack(0)

